    res=[]; I=A.copy()
    cands={'I':I,'ud':A[::-1],'lr':A[:,::-1],'udlr':A[::-1,::-1],
           't':A.T,'td':A.T[::-1],'tl':A.T[:,::-1],'b':A[::-1,:][:, ::-1] if False else A[::-1][::-1,:][:,::-1] if False else None}
